    create_location() {
      this.componentCheck = 1;
      this.addAssetLocationDialog = true;
    },
    on_location_setting_change(value) {
      if (value === "customLocation") {
        this.tableLoading = true;
        this.assetLocation = [];
        this.fetch_asset_locations("LIST"); // Call your query here
      }
    },
    async fetch_asset_locations(value) {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(asset_config_create_list_update_locations, {
          input: {
            action_type: value,
            is_asset_location_configured: value == "CONFIGURE" ? false : undefined,
            organization_id: data.organization.organization_id

            //   asset_location_name: this.locationName,
            //   asset_location_lat:
            //     this.geoLattitude == "" ? undefined : this.geoLattitude,
            //   asset_location_long:
            //     this.geoLongitude == "" ? undefined : this.geoLongitude,
          }
        }));
        var response = JSON.parse(result.data.asset_config_create_list_update_locations);
        this.tableLoading = false;
        this.loading = false;
        if (response.Status == "SUCCESS") {
          if (value == "CONFIGURE") {
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "green",
              SnackbarText: response.Message,
              timeout: 5000,
              Top: true
            };
          }
          if (value == "LIST") {
            this.loading = false;
            this.assetLocation = response.data;
          }
        } else {
          this.tableLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
      }
    },
    save_action(value) {
      this.loading = true;
      this.fetch_asset_locations(value);
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addAssetLocationDialog = false;
      this.deleteDialog = false;
      this.locationViewDialog = false;
      this.assetLocation = [];
      this.tableLoading = true;
      this.fetch_asset_locations("LIST");
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    }
